<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import MarkdownIt from 'markdown-it'
import type { Options as MarkdownItOptions } from 'markdown-it'
import hljs from 'highlight.js/lib/core'
import java from 'highlight.js/lib/languages/java'
import xml from 'highlight.js/lib/languages/xml'
import javascript from 'highlight.js/lib/languages/javascript'
import typescript from 'highlight.js/lib/languages/typescript'
import sql from 'highlight.js/lib/languages/sql'
import bash from 'highlight.js/lib/languages/bash'
import json from 'highlight.js/lib/languages/json'
import yaml from 'highlight.js/lib/languages/yaml'
import properties from 'highlight.js/lib/languages/properties'
import { navGroups, docFileMap } from '@/config/nav'

hljs.registerLanguage('java', java)
hljs.registerLanguage('xml', xml)
hljs.registerLanguage('html', xml)
hljs.registerLanguage('javascript', javascript)
hljs.registerLanguage('js', javascript)
hljs.registerLanguage('typescript', typescript)
hljs.registerLanguage('ts', typescript)
hljs.registerLanguage('sql', sql)
hljs.registerLanguage('bash', bash)
hljs.registerLanguage('sh', bash)
hljs.registerLanguage('json', json)
hljs.registerLanguage('yaml', yaml)
hljs.registerLanguage('yml', yaml)
hljs.registerLanguage('properties', properties)

const highlight = (str: string, lang: string): string => {
  if (lang && hljs.getLanguage(lang)) {
    try {
      return `<pre class="hljs"><code>${
        hljs.highlight(str, { language: lang, ignoreIllegals: true }).value
      }</code></pre>`
    } catch (_) {
      // ignore
    }
  }
  return `<pre class="hljs"><code>${md.utils.escapeHtml(str)}</code></pre>`
}

const mdOptions: MarkdownItOptions = {
  html: false,
  linkify: true,
  typographer: true,
  highlight
}

const md: MarkdownIt = new MarkdownIt(mdOptions)

// Vite 编译时把所有 markdown 当 raw 资源 import
const mdModules = import.meta.glob('@/docs/**/*.md', {
  query: '?raw',
  import: 'default',
  eager: true
}) as Record<string, string>

const route = useRoute()
const router = useRouter()
const content = ref<string>('加载中...')

const currentKey = computed(() => {
  const cat = route.params.category as string
  const slug = route.params.slug as string
  return `${cat}-${slug}`
})

function loadDoc(key: string) {
  const filePath = docFileMap[key]
  if (!filePath) {
    content.value = '## 文档不存在或正在编写中...'
    return
  }
  // 转成 glob 用的绝对 key
  const foundKey = Object.keys(mdModules).find((k) => k.endsWith('/' + filePath))
  const raw = foundKey ? mdModules[foundKey] : null
  if (!raw) {
    content.value = `## 文档文件未找到\n\n请检查 \`site/src/${filePath}\` 是否存在。`
    return
  }
  content.value = md.render(raw)
}

watch(
  currentKey,
  (k) => loadDoc(k),
  { immediate: true }
)

// 上下篇导航
const navInfo = computed(() => {
  const flat: { group: string; base: string; title: string; path: string }[] = []
  for (const g of navGroups) {
    for (const it of g.items) {
      flat.push({ group: g.title, base: g.base, title: it.title, path: it.path })
    }
  }
  const idx = flat.findIndex(
    (x) => x.base.endsWith('/' + (route.params.category as string)) && x.path === (route.params.slug as string)
  )
  return {
    prev: idx > 0 ? flat[idx - 1] : null,
    next: idx >= 0 && idx < flat.length - 1 ? flat[idx + 1] : null
  }
})

function goTo(item: { base: string; path: string } | null) {
  if (item) router.push(item.base + '/' + item.path)
}
</script>

<template>
  <div class="doc-page">
    <!-- 左侧目录 -->
    <aside class="doc-aside">
      <div class="aside-inner">
        <h3>学习目录</h3>
        <div v-for="g in navGroups" :key="g.title" class="aside-group">
          <div class="aside-group-title">{{ g.title }}</div>
          <RouterLink
            v-for="it in g.items"
            :key="it.path"
            :to="g.base + '/' + it.path"
            class="aside-link"
            :class="{
              active:
                g.base.endsWith('/' + (route.params.category as string)) &&
                it.path === (route.params.slug as string)
            }"
          >
            {{ it.title }}
          </RouterLink>
        </div>
      </div>
    </aside>

    <!-- 内容 -->
    <article class="doc-content" v-html="content" />

    <!-- 右侧上下篇 -->
    <aside class="doc-pager">
      <div class="pager-inner">
        <h4>📍 上下篇</h4>
        <button
          v-if="navInfo.prev"
          class="pager-btn prev"
          @click="goTo(navInfo.prev)"
        >
          <span class="pager-label">← 上一篇</span>
          <span class="pager-title">{{ navInfo.prev.title }}</span>
        </button>
        <button
          v-if="navInfo.next"
          class="pager-btn next"
          @click="goTo(navInfo.next)"
        >
          <span class="pager-label">下一篇 →</span>
          <span class="pager-title">{{ navInfo.next.title }}</span>
        </button>
      </div>
    </aside>
  </div>
</template>

